namespace MermaidSharp.Samples
{
    /// <summary>
    /// Represents a sample diagram with its generated Mermaid definition.
    /// </summary>
    /// <param name="Kind">The diagram type.</param>
    /// <param name="Id">A unique, URL-friendly identifier.</param>
    /// <param name="Title">The display title.</param>
    /// <param name="Description">What the example demonstrates.</param>
    /// <param name="Definition">The Mermaid definition generated by MermaidSharp.</param>
    public sealed record DiagramExample(DiagramKind Kind, string Id, string Title, string Description, string Definition)
    {
        /// <summary>
        /// Gets the display name of the diagram type.
        /// </summary>
        public string Category => Kind switch
        {
            DiagramKind.Flowchart => "Flowchart",
            DiagramKind.ClassDiagram => "Class diagram",
            DiagramKind.EntityRelationship => "Entity relationship",
            DiagramKind.GitGraph => "Git graph",
            DiagramKind.PieChart => "Pie chart",
            DiagramKind.QuadrantChart => "Quadrant chart",
            DiagramKind.XYChart => "XY chart",
            DiagramKind.AutoDiagram => "AutoDiagram (reflection)",
            _ => Kind.ToString()
        };
    }
}
